        btnResetParams.onClick = function () {
            var comp = app.project.activeItem;
            if (!(comp instanceof CompItem)) return alert("Please select a Composition.");
            var sel = comp.selectedLayers;
            if (sel.length !== 1 || !isAnyControlNull(sel[0])) {
                return alert("Select exactly 1 Control Null (Grid / Circular / Path) to reset its parameters.");
            }
            var pivot = sel[0];

            clBeginUndo("Reset Controller Params");
            try {
                var fx = pivot.property("ADBE Effect Parade");
                var changed = 0;

                // Reset dua he thong ve mac dinh -> go luon ca bo Reactive
                try { rvPurgeSystem(comp, pivot); } catch (eRv) {}

                for (var name in GRID_PARAM_DEFAULTS) {
                    var pr = null;
                    try { pr = fx.property(name); } catch (e) { pr = null; }
                    if (!pr) continue;
                    try {
                        var val = pr.property(1);
                        if (val.expression && val.expression !== "") continue;   // dang bi Expression lai, bo qua
                        var d = GRID_PARAM_DEFAULTS[name];
                        if (d instanceof Array) {
                            // Khop so chieu cua control hien tai
                            var cur = val.value;
                            val.setValue(cur.length > 2 ? [d[0], d[1], 0] : [d[0], d[1]]);
                        } else {
                            val.setValue(d);
                        }
                        changed++;
                    } catch (e) {}
                }

                // Bien do Random / Wiggle dang theo o luoi -> tra ve nua o
                var halfW = 50, halfH = 50;
                try { halfW = fx.property("Wide Gap").property(1).value / 2; } catch (e) {}
                try { halfH = fx.property("Height Gap").property(1).value / 2; } catch (e) {}
                var vecNames = ["Random Offset", "Wiggle Position Amp", "Wiggle Scale Amp"];
                for (var v = 0; v < vecNames.length; v++) {
                    var vp = null;
                    try { vp = fx.property(vecNames[v]); } catch (e) { vp = null; }
                    if (!vp) continue;
                    try {
                        var dflt = (vecNames[v] === "Random Offset") ? [halfW, halfH, (halfW + halfH) / 2] : [30, 30, 30];
                        var cv = vp.property(1).value;
                        vp.property(1).setValue(cv.length > 2 ? dflt : [dflt[0], dflt[1]]);
                        changed++;
                    } catch (e) {}
                }
                try {
                    var rz = fx.property("Random Offset Z");
                    if (rz) { rz.property(1).setValue((halfW + halfH) / 2); changed++; }
                } catch (e) {}

                alert("Reset done - " + changed + " parameter(s) back to default.\n\nLayout and structure were left untouched (Grid size, Total Clones, Radius, Gaps, Angle, Distance, Path link, mode checkboxes).");
            } catch (error) {
                alert("Error resetting params: " + error.toString());
            }
            clEndUndo();
        };

